// Collide function — checks if position overlaps with a player
import { game, players } from '../state';

// Returns -1 if no collision, otherwise returns player number (0 or 1)
export function collide(xPos: number, yPos: number): number {
  for (let c = 0; c <= game.players; c++) {
    if (players[c].dead === 0) { // FALSE = not dead
      if (players[c].status > -1 && players[c].status < 201) {
        if (xPos > players[c].x - 12 && xPos < players[c].x + 12) {
          if (yPos > players[c].y - 12 && yPos < players[c].y + 12) {
            return c;
          }
        }
      }
    }
  }
  return -1;
}

