/**
 * conversation.ts — NPC conversation state machine.
 *
 * Owns the dialog state (pages, paging, Yes/No choice, Asbestos Cape
 * purchase) and the tick-driven transitions. All side-effects (memory
 * reads/writes, almas deduction, item insertion, finish callbacks) go
 * through the injected deps; drawing stays with the caller, which reads
 * the public fields (boxX/Y/W/H etc.).
 */

import {
    ADDR_CALIENTE_ITEMS,
    ADDR_HERO_CREST,
    ADDR_NPC_CONVERSATIONS,
    ADDR_PLACE_MAP_ID,
    ADDR_SPACEBAR_LATCH,
} from '../core/memory.js';
import { LLAMA_TOWN_ID } from '../data/assets.js';
import { parseDialogText, type DialogEffects, type ParsedDialog } from './conversation-text.js';

export const ASBESTOS_CAPE_ITEM_ID = 5;
export const ASBESTOS_CAPE_PRICE = 2500;

/** First writable inventory slot scanned when inserting the cape. */
const ITEM_SLOT_SCAN_START = 0xa1;
/** Exclusive end of the item-slot scan (legacy loop condition slot < 0xFF). */
const ITEM_SLOT_SCAN_END = 0xff;

/** g_mem word holding the interacting NPC's struct address during talk. */
const ADDR_NPC_ADDR_LATCH = 0xfff6;

// Yes/No response conversation patterns (kept / refused).
const PATTERN_YES_RESPONSE = 0x0c;
const PATTERN_NO_RESPONSE = 0x0d;
// Asbestos Cape follow-up patterns.
const PATTERN_NOT_FREE = 5; // "It's not free though..."
export const PATTERN_REFUSED = 6;
export const PATTERN_NO_ALMAS = 7;
export const PATTERN_BOUGHT = 8;
const PATTERN_CAPE_ONLY_TALK = 9;
const PATTERN_CREST_TEXT = 14;

/**
 * Walk the wasm NPC conversation pointer table: `ADDR_NPC_CONVERSATIONS`
 * points at a per-NPC array of text addresses; each text runs until 0xFF
 * (or an early 0x00 terminator). Returns null when the table, the entry,
 * or the text address is empty.
 */
export function readNpcConversationBytes(
    readMemory: (offset: number, length: number) => Uint8Array | null,
    npcId: number,
): Uint8Array | null {
    const ptr = readMemory(ADDR_NPC_CONVERSATIONS, 2) ?? new Uint8Array(2);
    const convTablePtr = (ptr[0] ?? 0) | ((ptr[1] ?? 0) << 8);
    if (!convTablePtr) return null;
    const textPtr = readMemory(convTablePtr + npcId * 2, 2) ?? new Uint8Array(2);
    const textAddr = (textPtr[0] ?? 0) | ((textPtr[1] ?? 0) << 8);
    if (!textAddr) return null;
    const bytes: number[] = [];
    let b: number;
    while ((b = (readMemory(textAddr + bytes.length, 1) ?? new Uint8Array(1))[0] ?? 0xff) !== 0xff) {
        if (b === 0) break;
        bytes.push(b);
    }
    return new Uint8Array(bytes);
}

export interface ConversationDeps {
    readMemory(offset: number, length: number): Uint8Array | null;
    writeMemory(offset: number, data: ArrayLike<number>): void;
    /** Fetch raw conversation bytes for a pattern id (null when absent). */
    getNpcConversationRaw(npcId: number): Uint8Array | null;
    /**
     * Fetch an already-parsed localized conversation for a pattern id (null
     * when the active locale has no translation). When present it takes
     * precedence over the raw bytes, because Unicode text cannot round-trip
     * through the ASCII byte pipeline.
     */
    getLocalizedConversation?(npcId: number): ParsedDialog | null;
    /** Clear the wasm-side conversation-active latch. */
    townFinishConversation(): void;
    getHeroAlmasValue(): number;
    setHeroAlmasValue(value: number): void;
    renderAlmasHud(): void;
    /**
     * Recompute the dialog box rectangle for the current page and store the
     * result into boxX/Y/W/H (game.js measures text via its canvas context).
     */
    layout(facingLeft: unknown, extraLines?: number): void;
    /**
     * Control-code side effects applied while parsing dialog bytes
     * (0x83 Elf Crest grant, 0x8B tear collection). Without these the
     * engine state mutations behind those codes never happen.
     */
    effects?: DialogEffects;
}

export class ConversationManager {
    // Public state — read by game.js's draw function and scene guards,
    // field names identical to the legacy object for a drop-in swap.
    active = false;
    pages: string[][] = [];
    page = 0;
    pageSize = 6;
    hasYesNo = false;
    yesNoMode = false;
    yesNoCursor = 0;
    purchaseMode = false;
    purchaseCursor = 0;
    endCode: number | null = null;
    facingLeft: unknown = false;
    savedBackground: unknown = null;
    onComplete: (() => void) | null = null;

    boxX = 0;
    boxY = 0;
    boxW = 0;
    boxH = 0;

    private readonly deps: ConversationDeps;

    constructor(deps: ConversationDeps) {
        this.deps = deps;
    }

    /** readMemory that mirrors the engine-ready assumption of the legacy code. */
    private mem(offset: number, length: number): Uint8Array {
        return this.deps.readMemory(offset, length) ?? new Uint8Array(length);
    }

    /**
     * Resolve a pattern id: a localized (Unicode-aware) parse when the active
     * locale provides one, otherwise the original ASCII MDT bytes.
     */
    private parsePattern(npcId: number): ParsedDialog | null {
        const localized = this.deps.getLocalizedConversation?.(npcId) ?? null;
        if (localized && localized.pages.length > 0) return localized;
        const raw = this.deps.getNpcConversationRaw(npcId);
        const parsed = parseDialogText(raw ?? [], this.deps.effects);
        return parsed.pages.length > 0 ? parsed : null;
    }


    /** Deactivate + clear wasm latch (+ optional completion callback). */
    close(callOnComplete = false): void {
        const onComplete = this.onComplete;
        this.active = false;
        this.savedBackground = null;
        this.onComplete = null;
        this.deps.townFinishConversation();
        if (callOnComplete && onComplete) onComplete();
    }

    /**
     * Start the conversation triggered by the wasm town code (space near an
     * NPC). No-op-safe: leaves state untouched when there is nothing to say.
     */
    startFromWasm(): void {
        const npcAddrBytes = this.mem(ADDR_NPC_ADDR_LATCH, 2);
        const npcAddr = (npcAddrBytes[0] ?? 0) | ((npcAddrBytes[1] ?? 0) << 8);
        let npcId = 0;
        if (npcAddr) {
            npcId = this.mem(npcAddr + 7, 1)[0] ?? 0;
        }
        // After buying the Asbestos Cape in Llama, its merchant (npc id 3)
        // stops re-selling it and only talks about the cape (pattern 9).
        if (
            npcId === 3 &&
            ((this.mem(ADDR_CALIENTE_ITEMS, 1)[0] ?? 0) & 0x40) !== 0 &&
            ((this.mem(ADDR_PLACE_MAP_ID, 1)[0] ?? 0) & 0x7f) === LLAMA_TOWN_ID
        ) {
            npcId = PATTERN_CAPE_ONLY_TALK;
        }

        const parsed = this.parsePattern(npcId);
        if (!parsed) {
            this.deps.townFinishConversation();
            return;
        }

        // Hero Crest holders get different yes/no phrasing (pattern 14).
        if (this.mem(ADDR_HERO_CREST, 1)[0] && parsed.hasYesNo) {
            const crestParsed = this.parsePattern(PATTERN_CREST_TEXT);
            if (!crestParsed) {
                this.deps.townFinishConversation();
                return;
            }
            this.applyParsed(crestParsed, false);
        } else {
            this.applyParsed(parsed, false);
        }

        const facingLeft = npcAddr ? (this.mem(npcAddr + 2, 1)[0] ?? 0) & 0x80 : false;
        this.facingLeft = facingLeft;
        this.deps.layout(facingLeft);
    }

    /** Load a conversation pattern; deactivates when it is empty. */
    loadPattern(patternIdx: number): void {
        const parsed = this.parsePattern(patternIdx);
        if (!parsed) {
            this.close();
            return;
        }
        this.applyParsed(parsed, true);
        this.deps.layout(this.facingLeft);
    }

    /**
     * Start a dialog from pre-parsed pages with a completion callback
     * (e.g. the Pureza warp building's "Fooled again..." dialog). The caller
     * runs its own parse (it may need custom control-code effects); no-ops
     * are the caller's responsibility — parsed pages must be non-empty.
     */
    startDialog(parsed: ParsedDialog, onComplete: () => void): void {
        this.applyParsed(parsed, false);
        this.onComplete = onComplete;
        this.deps.layout(this.facingLeft);
    }

    private applyParsed(parsed: ParsedDialog, keepFacingLeft: boolean): void {
        this.active = true;
        this.pages = parsed.pages;
        this.page = 0;
        this.hasYesNo = parsed.hasYesNo;
        this.yesNoMode = false;
        this.yesNoCursor = 0;
        this.purchaseMode = false;
        this.purchaseCursor = 0;
        this.endCode = parsed.endCode;
        if (!keepFacingLeft) this.facingLeft = false;
        this.savedBackground = null;
        this.onComplete = null;
    }

    private spaceLatched(): boolean {
        const latched = this.mem(ADDR_SPACEBAR_LATCH, 1)[0];
        if (latched) this.deps.writeMemory(ADDR_SPACEBAR_LATCH, [0]);
        return !!latched;
    }

    private moveChoiceCursor(current: number, dirUp: boolean, dirDown: boolean): number {
        let cursor = current;
        if (dirUp && cursor > 0) cursor--;
        else if (dirDown && cursor < 1) cursor++;
        return cursor;
    }

    /**
     * One conversation tick (town mode only). Direction edges are computed by
     * the caller because they share edge state with other input paths.
     */
    handleTick(dirUp: boolean, dirDown: boolean): void {
        if (!this.active) return;
        const spaceLatched = this.spaceLatched();

        if (this.purchaseMode) {
            this.purchaseCursor = this.moveChoiceCursor(this.purchaseCursor, dirUp, dirDown);
            if (spaceLatched) this.handlePurchaseSelection(this.purchaseCursor === 0);
            return;
        }

        if (this.yesNoMode) {
            this.yesNoCursor = this.moveChoiceCursor(this.yesNoCursor, dirUp, dirDown);
            if (spaceLatched) this.handleYesNoSelection(this.yesNoCursor === 0);
            return;
        }

        if (!spaceLatched) return;

        if (this.page < this.pages.length - 1) {
            this.page++;
            this.deps.layout(this.facingLeft);
        } else if (this.hasYesNo) {
            this.yesNoMode = true;
            this.yesNoCursor = 0;
            this.deps.layout(this.facingLeft, 2);
        } else if (this.endCode === 0x87) {
            // Asbestos cape: second part ("It's not free though...")
            this.endCode = null;
            this.loadPattern(PATTERN_NOT_FREE);
        } else if (this.endCode === 0x89) {
            // Asbestos cape: Take/No-Take purchase confirmation
            this.endCode = null;
            this.purchaseMode = true;
            this.purchaseCursor = 0;
            this.deps.layout(this.facingLeft, 2);
        } else {
            this.close(true);
        }
    }

    private handleYesNoSelection(selectedYes: boolean): void {
        this.active = false;
        this.savedBackground = null;
        this.yesNoMode = false;
        this.hasYesNo = false;

        const responsePattern = selectedYes ? PATTERN_YES_RESPONSE : PATTERN_NO_RESPONSE;
        const parsed = this.parsePattern(responsePattern);
        if (!parsed) {
            // Nothing more to show: release the wasm conversation latch now.
            this.deps.townFinishConversation();
            return;
        }
        // Keep the wasm conversation latch set while the response text is on
        // screen (matches the original conversation loop): hero movement stays
        // blocked until the final space press closes the dialog via close().
        this.active = true;
        this.pages = parsed.pages;
        this.page = 0;
        this.hasYesNo = false;
        this.endCode = null;
        this.savedBackground = null;
        this.deps.layout(this.facingLeft);
    }

    private handlePurchaseSelection(take: boolean): void {
        if (take) {
            // Buy the Asbestos Cape for 2500 almas.
            const almas = this.deps.getHeroAlmasValue();
            if (almas >= ASBESTOS_CAPE_PRICE) {
                this.deps.setHeroAlmasValue(almas - ASBESTOS_CAPE_PRICE);
                this.deps.renderAlmasHud();
                // caliente_items bit6 = bought Asbestos Cape
                const ci = this.mem(ADDR_CALIENTE_ITEMS, 1)[0] ?? 0;
                this.deps.writeMemory(ADDR_CALIENTE_ITEMS, [ci | 0x40]);
                // Insert the cape (item id 5) into the first empty inventory slot.
                for (let slot = ITEM_SLOT_SCAN_START; slot < ITEM_SLOT_SCAN_END; slot++) {
                    if (this.mem(slot, 1)[0] === 0) {
                        this.deps.writeMemory(slot, [ASBESTOS_CAPE_ITEM_ID]);
                        break;
                    }
                }
                this.loadPattern(PATTERN_BOUGHT);
            } else {
                this.loadPattern(PATTERN_NO_ALMAS);
            }
        } else {
            this.loadPattern(PATTERN_REFUSED);
        }
    }
}

dmitrysmagin-lala-prologue-js-src-engine.text:
/**
 * Phase 8 — Player physics (ported from ENGINE.BAS:557-701)
 * engineMovePlayer: gravity, jumping, horizontal movement, tile collision,
 * edge detection, keyhole unlocking, evil tiles, flicker state.
 *
 * Fixed-point coords: x,y in 1/64 px. Convert:
 *   worldPixel = fixed >> 6
 *   tileCoord  = fixed >> 10  (>>6 then >>4)
 * Screen edges: x < 0 → DLEFT, x > 19456 → DRIGHT, y < 0 → DUP, y > 11264 → DDOWN
 */
import { Keyboard, SC_LEFT, SC_RIGHT, SC_UP, SC_CTRL } from "../keyboard";
import { STATENORMAL, STATEFLICKER, DLEFT, DRIGHT, DUP, DDOWN, cToIdx } from "./types";
import { engineDetectKeyHole } from "./collision";
import type { TypePlayer, TypeTileLayers, TypePrefs } from "./types";

/** Callback type for triggering sound effects — keeps player.ts decoupled from audio */
export type PlaySfx = (slot: number, loop?: boolean, freq?: number) => void;
/** Callback for stopping a specific voice */
export type StopSfx = (voice: number) => void;
const noopSfx: PlaySfx = () => {};

/**
 * ENGINE.BAS:557 — SUB engineMovePlayer(curScreenBuff, player, prefs, map())
 * Processes one frame of player physics. Sets player.attempt if edge reached.
 *
 * @param keyboard  — Keyboard instance for reading arrow/ctrl state
 * @param curScreenBuff — 22×14 letterboxed tile buffer
 * @param player    — mutable player state
 * @param prefs     — game constants (gravity, speeds, etc.)
 * @param map       — flat tile map (for keyhole removal)
 */
export function engineMovePlayer(
  keyboard: Keyboard,
  curScreenBuff: TypeTileLayers[],
  player: TypePlayer,
  prefs: TypePrefs,
  map: Uint8Array,
  playSfx: PlaySfx = noopSfx,
): void {
  // Reset attempt each frame
  player.attempt = 0;

  // --- Flicker state ---
  if (player.state === STATEFLICKER) {
    player.ctState--;
    if (player.ctState === 0) {
      player.state = STATENORMAL;
    }
  }

  // ==========================
  // VERTICAL MOVEMENT (gravity)
  // ==========================
  player.vy += prefs.g;
  if (player.vy > prefs.gMaxVy) player.vy = prefs.gMaxVy;
  player.y += player.vy;

  // Edge detection (vertical)
  if (player.y < 0) { player.y = 0; player.attempt = DUP; }
  if (player.y > 11264) { player.y = 11264; player.attempt = DDOWN; }

  // If on movable platform, zero vy
  if (player.gotten) player.vy = 0;

  // Recompute tile coords after vertical move
  let y = player.y >> 6;
  let yy = y >> 4;
  let x = player.x >> 6;
  let xx = x >> 4;

  // --- Vertical tile collision ---
  if (player.vy < 0) {
    // Moving up — check ceiling (behaviour > 7)
    const idx1 = cToIdx(xx, yy);
    const idx2 = (x & 15) !== 0 ? cToIdx(xx + 1, yy) : -1;
    if (curScreenBuff[idx1].behaviour > 7 || (idx2 >= 0 && curScreenBuff[idx2].behaviour > 7)) {
      player.vy += prefs.jumpIncr >> 1;
      player.y = (yy + 1) << 10;
      y = player.y >> 6;
      yy = y >> 4;
    }
  } else if (player.vy > 0 && (y & 15) <= (prefs.gMaxVy >> 6)) {
    // Moving down — check floor (behaviour > 3)
    const idx1 = cToIdx(xx, yy + 1);
    const idx2 = (x & 15) !== 0 ? cToIdx(xx + 1, yy + 1) : -1;
    if (curScreenBuff[idx1].behaviour > 3 || (idx2 >= 0 && curScreenBuff[idx2].behaviour > 3)) {
      player.vy = 0;
      player.y = yy << 10;
      y = player.y >> 6;
      yy = y >> 4;
    }
  }

  // ==========================
  // JUMPING (Ctrl or Up arrow)
  // ==========================
  if (keyboard.isDown(SC_CTRL) || keyboard.isDown(SC_UP)) {
    if (player.vy === 0 && !player.jumping) {
      // Must be on ground or on platform
      const onGround =
        player.gotten ||
        curScreenBuff[cToIdx(xx, yy + 1)].behaviour > 3 ||
        ((x & 15) !== 0 && curScreenBuff[cToIdx(xx + 1, yy + 1)].behaviour > 3);
      if (onGround) {
        player.jumping = -1;
        player.ctJump = 0;
        // SFX: JUMP (slot 3) — slight pitch randomisation
        playSfx(3, false, 11025 + ((Math.random() * 1024) | 0));
        player.x = x << 6; // snap to tile grid
      }
    }
    if (player.jumping) {
      player.vy -= prefs.jumpVyInitial + prefs.jumpIncr - (player.ctJump >> 1);
      if (player.vy < -prefs.jumpVyMax) player.vy = -prefs.jumpVyMax;
      player.ctJump++;
      if (player.ctJump === 16) {
        player.jumping = 0;
      }
    }
  } else {
    player.jumping = 0;
  }

  // ==========================
  // HORIZONTAL MOVEMENT
  // ==========================

  // Friction when no left/right key
  if (!(keyboard.isDown(SC_LEFT) || keyboard.isDown(SC_RIGHT))) {
    if (player.vx > 0) {
      player.vx -= prefs.walkFr;
      if (player.vx < 0) { player.vx = 0; player.x = x << 6; }
    } else if (player.vx < 0) {
      player.vx += prefs.walkFr;
      if (player.vx > 0) { player.vx = 0; player.x = x << 6; }
    }
  }

  // Accelerate left
  if (keyboard.isDown(SC_LEFT)) {
    if (player.vx > -prefs.walkVxMax) {
      player.facing = 6;
      player.vx -= prefs.walkAx;
    }
  }

  // Accelerate right
  if (keyboard.isDown(SC_RIGHT)) {
    if (player.vx < prefs.walkVxMax) {
      player.facing = 0;
      player.vx += prefs.walkAx;
    }
  }

  // Apply horizontal velocity
  player.x += player.vx;

  // Edge detection (horizontal)
  if (player.x < 0) { player.x = 0; player.attempt = DLEFT; }
  if (player.x > 19456) { player.x = 19456; player.attempt = DRIGHT; }

  // Recompute tile coords after horizontal move
  x = player.x >> 6;
  xx = x >> 4;
  y = player.y >> 6;
  yy = y >> 4;

  // --- Horizontal tile collision ---
  if (player.vx < 0) {
    // Moving left — check wall (behaviour > 7)
    const idx1 = cToIdx(xx, yy);
    const idx2 = (y & 15) !== 0 ? cToIdx(xx, yy + 1) : -1;
    if (curScreenBuff[idx1].behaviour > 7 || (idx2 >= 0 && curScreenBuff[idx2].behaviour > 7)) {
      player.vx = 0;
      player.x = (xx + 1) << 10;
    }
  } else if (player.vx > 0) {
    // Moving right — check wall (behaviour > 7)
    const idx1 = cToIdx(xx + 1, yy);
    const idx2 = (y & 15) !== 0 ? cToIdx(xx + 1, yy + 1) : -1;
    if (curScreenBuff[idx1].behaviour > 7 || (idx2 >= 0 && curScreenBuff[idx2].behaviour > 7)) {
      player.vx = 0;
      player.x = xx << 10;
    }
  } else {
    // No horizontal velocity — snap to tile grid
    player.x = x << 6;
  }

  // Final tile coords
  x = player.x >> 6;
  xx = x >> 4;
  y = player.y >> 6;
  yy = y >> 4;

  // ==========================
  // KEYHOLE UNLOCKING
  // ==========================
  if ((y & 15) === 0 && (x & 15) === 0 && player.keys > 0) {
    let opened = false;
    if (keyboard.isDown(SC_LEFT)) opened = engineDetectKeyHole(curScreenBuff, map, xx - 1, yy);
    if (keyboard.isDown(SC_RIGHT)) opened = engineDetectKeyHole(curScreenBuff, map, xx + 1, yy);
    if (opened) {
      player.keys--;
      // SFX: BOLT (slot 1) — keyhole unlock
      playSfx(1);
    }
  }

  // ==========================
  // EVIL TILES (behaviour == 1)
  // ==========================
  const ev1 = curScreenBuff[cToIdx(xx, yy)].behaviour === 1;
  const ev2 = (x & 15) !== 0 && curScreenBuff[cToIdx(xx + 1, yy)].behaviour === 1;
  const ev3 = (y & 15) !== 0 && curScreenBuff[cToIdx(xx, yy + 1)].behaviour === 1;
  const ev4 = (x & 15) !== 0 && (y & 15) !== 0 && curScreenBuff[cToIdx(xx + 1, yy + 1)].behaviour === 1;
  if (ev1 || ev2 || ev3 || ev4) {
    // SFX: PINCHE (slot 7) — always plays on evil tile
    playSfx(7);
    if (player.state === STATENORMAL) {
      // SFX: AH (slot 8) — pain vocal only when not already flickering
      playSfx(8, false, 11025 + ((Math.random() * 1024) | 0));
      player.lives--;
      player.state = STATEFLICKER;
      player.ctState = 128;
    }
    // Knockback: reverse vertical velocity
    if (player.vy < 0) {
      player.vy = prefs.gMaxVy;
      player.y = (yy + 1) << 10;
    } else {
      player.vy = -prefs.gMaxVy;
      player.y = yy << 10;
    }
  }
}

