using System.Text.Json;

namespace GameOverPC;

sealed partial class NativeGame
{
    sealed class SpawnRecord
    {
        public int Kind {get;set;}
        public int SpawnThreshold {get;set;}
        public int? XByte {get;set;}
        public int? Y {get;set;}
    }
    sealed class SpawnRoom { public int Room {get;set;} public SpawnRecord[] Entries {get;set;}=[]; }
    sealed class SpawnCatalog { public SpawnRoom[] Rooms {get;set;}=[]; }
    SpawnCatalog? spawnCatalog;
    SpawnRecord[] roomSpawns=[];
    readonly Random enemyRandom=new(1986);
    bool encounterActive;
    int encounterKind;
    readonly HashSet<int> defeatedEncounters=[];
    public bool EncounterBlocksExit=>encounterActive&&Enemies.Any(e=>!e.Dead);

    // Coordinates, spawn descriptors, health and sprite addresses are recovered.
    // RNG scheduling and attack cadence use native ticks until CPC timing is measured.
    public void LoadEnemies()
    {
        Enemies.Clear();encounterActive=false;encounterKind=0;
        if(spawnCatalog==null)
        {
            string path=Path.Combine(AppContext.BaseDirectory,"assets",$"enemies{Part}.json");
            spawnCatalog=JsonSerializer.Deserialize<SpawnCatalog>(File.ReadAllText(path),new JsonSerializerOptions{PropertyNameCaseInsensitive=true});
        }
        roomSpawns=spawnCatalog?.Rooms.FirstOrDefault(r=>r.Room==Room)?.Entries??[];
        var special=roomSpawns.FirstOrDefault(r=>r.Kind>2);
        if(special!=null&&!defeatedEncounters.Contains(Room))
        {
            encounterActive=true;encounterKind=special.Kind;
            if(Part==1&&special.Kind==4)AddEnemy(4,45,36,40);
            else if(Part==1&&special.Kind==5)
            {AddEnemy(5,58,60,8);AddEnemy(5,135,60,8);AddEnemy(5,100,60,8);}
            else if(Part==2&&special.Kind==4){Checkpoint=22;AddEnemy(4,80,24,100);}
        }
        if(defeatedEncounters.Contains(Room))roomSpawns=[];
        if(!encounterActive)TrySpawnEnemy(true);
        if(Part==2)
        {
            if(Room==15)AddEnemy(6,29,24,10);
            if(Room==19)AddEnemy(6,42,24,10);
            if(Room==21)AddEnemy(6,36,80,10);
        }
    }
    void AddEnemy(int kind,float x,float y,int health=1)
    {
        if(Part==2&&kind<=2)health=kind+1;
        var e=new Foe{Kind=kind,X=x,Y=y,OriginX=x,Health=health,Dx=x>58?-1:1};
        if(Part==2){e.Dx=kind==2?1:2;if(x>58&&x<=150)e.Dx=-e.Dx;else if(kind==0)e.Dx=-2;}
        if(Part==1&&kind<2)e.Dx=x<0?kind+1:-(kind+1);
        if(Part==1&&kind==5)e.Dx=-1;
        SetEnemyFrame(e);Enemies.Add(e);
    }
    void TrySpawnEnemy(bool initial=false)
    {
        if(encounterActive||Enemies.Count(e=>!e.Dead)>=4)return;
        foreach(var record in roomSpawns.Where(r=>r.Kind<=2))
        {
            int threshold=record.SpawnThreshold+(Part==2?26:0);
            if(!initial&&enemyRandom.Next(256)>=threshold)continue;
            if(Part==2||record.Kind==2)AddEnemy(record.Kind,record.XByte??0,record.Y??0);
            else
            {
                bool left=enemyRandom.Next(2)==0;
                AddEnemy(record.Kind,left?-6:56,enemyRandom.Next(24)*8);
            }
            break;
        }
    }
    void SetEnemyFrame(Foe e)
    {
        int address;
        if(Part==1)
        {
            // 8278/8298 contain the original forward/reverse attack frame lists.
            int phase=e.Age%32;
            address=e.Kind switch {
                0=>(e.Dx<0?0x52c2:0x4fe8),
                1=>(e.Dx<0?0x56e2:0x5354),
                2=>(e.Dx<0?0x5888:0x5764)+(e.Age%2)*0x92,
                4=>0x5d44,
                5=>0x5fb6+((e.Age%6)/2)*0x182,_=>0x5764};
            if(e.Kind<=1&&phase< (e.Kind==0?7:8))
            {
                int[] sequence=e.Kind==0?[0x4fe8,0x507a,0x510c,0x519e,0x5230,0x52c2,0x4fe8]:[0x5354,0x53d6,0x5458,0x54da,0x555c,0x55de,0x5660,0x56e2];
                address=sequence[e.Dx<0?sequence.Length-1-phase:phase];
            }
        }
        else
        {
            address=e.Kind switch {0=>0x58de+(e.Age%3)*0xf2,1=>(e.Dx<0?0x5d38:0x5bb4)+(e.Age%2)*0xc2,2=>(e.Dx<0?0x6102:0x5ebc)+(e.Age%3)*0xc2,4=>e.Age%24<4?0x398a:0x3938,6=>0x6522,_=>0x5bb4};
        }
        var frame=Data.Sprites.Frames.FirstOrDefault(f=>f.Address==address);
        if(frame!=null)e.Frame=frame.Id;
    }
    (float Width,float Height) EnemySize(Foe e)
    {
        if(Part==1&&e.Kind==4)return(13,72);
        if(Part==2&&e.Kind==4)return(8,63); // 22EC..2305: head and48line body collider
        var frame=Data.Sprites.Frames.FirstOrDefault(f=>f.Id==e.Frame);
        return frame==null?(6,24):(frame.Width/2f,frame.Height);
    }
    void UpdateEnemies()
    {
        if(encounterActive&&Enemies.All(e=>e.Dead))
        {
            defeatedEncounters.Add(Room);
            encounterActive=false;roomSpawns=[];
            if(Part==2&&encounterKind==4){Complete=true;Sound?.Invoke("complete");}
            return;
        }
        Enemies.RemoveAll(e=>e.Dead);
        if(Tick%5==0)TrySpawnEnemy();
        foreach(var e in Enemies)
        {
            e.Age++;
            if(e.Kind<=2)
            {
                e.X+=e.Dx;
                if(Part==1&&e.Kind==0)e.Y+=Math.Clamp(Y-8-e.Y,-2,2);
                if(Part==2&&e.Kind==0)
                {
                    var floor=Hit(e.X+4,e.Y+40,2,2,Solid);
                    if(floor==null)e.Y+=4;else e.Y=Signed(floor.Row)-40;
                }
                if(e.X>60||e.X< -8){e.Dead=true;continue;}
                bool attack=Part==1
                    ? e.Age%32==(e.Kind<=1?6+2*e.Kind:8)
                    : e.Kind>0&&e.Age%32==8;
                if(attack&&e.X>=0&&e.X<=58)
                    Shots.Add(new Shot{X=e.X+(X<e.X?-1:6),Y=e.Y+8,Dx=X<e.X?-2:2,Enemy=true,Life=40});
            }
            else
            {
                if(Part==2&&e.Kind==4)
                {
                    // Original entrance1E9E: column80 to42 at-1/tick, then30tickwait.
                    // Later24..42 vertical attack cycle and pursuit timing approximate
                    // the recovered states1F18/2046/207A until runtime tracing.
                    if(e.Age<=38)e.X=80-e.Age;
                    else if(e.Age>68)
                    {
                        int phase=(e.Age-68)%40;
                        e.Y=phase<6?24+phase*3:phase<15?42-(phase-6)*2:24;
                        if(phase<6)e.X=Math.Max(8,e.X-2);
                        else if(phase>=15&&phase<30)e.X=Math.Min(48,e.X+2);
                    }
                }
                // Recovered encounters keep their original position, hit count and art;
                // attack scheduling is a native approximation, not a Z80 timing claim.
                // Hydra records start at byte columns58,135,100, advancing left;
                // delayed entrances must not be replaced by arbitrary visible positions.
                if(e.Kind==5)
                {
                    e.X+=e.Dx;
                    if(e.X<0){e.X=0;e.Dx=1;}
                    else if(e.X<=58&&e.Dx>0&&e.X>=56)e.Dx=-1;
                }
                if(e.Age%24==0&&e.X<=58)Shots.Add(new Shot{X=e.X,Y=e.Y+12,Dx=X<e.X?-2:2,Dy=Math.Clamp((Y-e.Y)/Math.Max(1,Math.Abs(X-e.X)/2),-4,4),Enemy=true,Life=40});
            }
            SetEnemyFrame(e);
            var size=EnemySize(e);
            if(Overlap(e.X,e.Y,size.Width,size.Height,X,Y,6,24))Damage(3);
        }
    }
}

